Game source (line-numbered):
1| <!doctype html>
2| <html lang="en">
3| <head>
4| <meta charset="utf-8">
5| <meta name="viewport" content="width=device-width, initial-scale=1">
6| <title>Tiny Maze</title>
7| <style>
8|   html, body {
9|     margin: 0;
10|     padding: 0;
11|     width: 100%;
12|     height: 100%;
13|     overflow: hidden;
14|     background: #f4ecd8;
15|     touch-action: none;
16|   }
17|   canvas {
18|     display: block;
19|     touch-action: none;
20|   }
21| </style>
22| </head>
23| <body>
24| <canvas id="game"></canvas>
25| <script>
26| // ---- Bridge helper (verbatim) ----
27| const CARTRIDGE = {
28|   send(type, payload = {}) {
29|     window.parent.postMessage(
30|       { source: "cartridge", v: 1, type, payload },
31|       "*",
32|     );
33|   },
34| };
35| 
36| // ---- Game setup ----
37| const canvas = document.getElementById("game");
38| const ctx = canvas.getContext("2d");
39| 
40| let W = 0, H = 0, DPR = 1;
41| let paused = false;
42| let running = false; // has play begun
43| let booted = false;
44| 
45| const PALETTE = {
46|   bg: "#f4ecd8",
47|   layer: "#e07a5f",
48|   accent: "#3d405b",
49|   highlight: "#81b29a",
50| };
51| 
52| function resize() {
53|   DPR = window.devicePixelRatio || 1;
54|   W = window.innerWidth;
55|   H = window.innerHeight;
56|   canvas.width = Math.floor(W * DPR);
57|   canvas.height = Math.floor(H * DPR);
58|   canvas.style.width = W + "px";
59|   canvas.style.height = H + "px";
60|   ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
61|   draw();
62| }
63| window.addEventListener("resize", resize);
64| 
65| // ---- Seeded jitter helper for paper-cut edges ----
66| function mulberry32(a) {
67|   return function () {
68|     a |= 0; a = (a + 0x6D2B79F5) | 0;
69|     let t = Math.imul(a ^ (a >>> 15), 1 | a);
70|     t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
71|     return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
72|   };
73| }
74| 
75| // ---- Maze generation ----
76| const GRID = 7; // GRID x GRID maze
77| let cells = []; // cells[y][x] = {walls:{N,S,E,W}, visited}
78| let playerX = 0, playerY = 0;
79| let goalX = GRID - 1, goalY = GRID - 1;
80| let moves = 0;
81| let score = 0;
82| let level = 1;
83| let mazeSeed = 1;
84| let jitterRand = null;
85| let cellJitter = []; // per-cell jitter offsets
86| 
87| function genMaze(seed) {
88|   const rand = mulberry32(seed);
89|   cells = [];
90|   for (let y = 0; y < GRID; y++) {
91|     const row = [];
92|     for (let x = 0; x < GRID; x++) {
93|       row.push({ N: true, S: true, E: true, W: true, visited: false });
94|     }
95|     cells.push(row);
96|   }
97|   // iterative DFS backtracker
98|   const stack = [];
99|   let cx = 0, cy = 0;
100|   cells[cy][cx].visited = true;
101|   stack.push([cx, cy]);
102|   while (stack.length) {
103|     const [x, y] = stack[stack.length - 1];
104|     const neighbors = [];
105|     if (y > 0 && !cells[y - 1][x].visited) neighbors.push(["N", x, y - 1]);
106|     if (y < GRID - 1 && !cells[y + 1][x].visited) neighbors.push(["S", x, y + 1]);
107|     if (x > 0 && !cells[y][x - 1].visited) neighbors.push(["W", x - 1, y]);
108|     if (x < GRID - 1 && !cells[y][x + 1].visited) neighbors.push(["E", x + 1, y]);
109|     if (neighbors.length === 0) {
110|       stack.pop();
111|       continue;
112|     }
113|     const [dir, nx, ny] = neighbors[Math.floor(rand() * neighbors.length)];
114|     const opp = { N: "S", S: "N", E: "W", W: "E" };
115|     cells[y][x][dir] = false;
116|     cells[ny][nx][opp[dir]] = false;
117|     cells[ny][nx].visited = true;
118|     stack.push([nx, ny]);
119|   }
120| }
121| 
122| function genCellJitter(seed) {
123|   const rand = mulberry32(seed + 999);
124|   cellJitter = [];
125|   for (let y = 0; y < GRID; y++) {
126|     const row = [];
127|     for (let x = 0; x < GRID; x++) {
128|       const pts = [];
129|       for (let i = 0; i < 4; i++) {
130|         pts.push([(rand() - 0.5) * 2, (rand() - 0.5) * 2]);
131|       }
132|       row.push(pts);
133|     }
134|     cellJitter.push(row);
135|   }
136| }
137| 
138| function newGame() {
139|   mazeSeed = Math.floor(Math.random() * 1000000) + 1;
140|   genMaze(mazeSeed);
141|   genCellJitter(mazeSeed);
142|   playerX = 0;
143|   playerY = 0;
144|   goalX = GRID - 1;
145|   goalY = GRID - 1;
146|   moves = 0;
147|   score = 0;
148| }
149| 
150| // ---- Legal moves ----
151| function canMove(x, y, dir) {
152|   if (x < 0 || y < 0 || x >= GRID || y >= GRID) return false;
153|   return !cells[y][x][dir];
154| }
155| 
156| function anyLegalMove() {
157|   const dirs = ["N", "S", "E", "W"];
158|   for (const d of dirs) {
159|     if (canMove(playerX, playerY, d)) return true;
160|   }
161|   return false;
162| }
163| 
164| function solved() {
165|   return playerX === goalX && playerY === goalY;
166| }
167| 
168| // ---- Layout math ----
169| function boardMetrics() {
170|   const margin = 40;
171|   const topArea = 90;
172|   const size = Math.min(W - margin * 2, H - topArea - margin);
173|   const boardSize = Math.max(size, 100);
174|   const cellSize = boardSize / GRID;
175|   const originX = (W - boardSize) / 2;
176|   const originY = topArea + (H - topArea - margin - boardSize) / 2;
177|   return { originX, originY, cellSize, boardSize };
178| }
179| 
180| function cellCenter(x, y) {
181|   const m = boardMetrics();
182|   return {
183|     cx: m.originX + x * m.cellSize + m.cellSize / 2,
184|     cy: m.originY + y * m.cellSize + m.cellSize / 2,
185|   };
186| }
187| 
188| function tileAt(px, py) {
189|   const m = boardMetrics();
190|   const gx = Math.floor((px - m.originX) / m.cellSize);
191|   const gy = Math.floor((py - m.originY) / m.cellSize);
192|   if (gx < 0 || gy < 0 || gx >= GRID || gy >= GRID) return null;
193|   return { gx, gy };
194| }
195| 
196| // ---- Drawing helpers (paper-cut style) ----
197| function jitterPoly(baseX, baseY, w, h, jitterPts) {
198|   // returns 4 corner points with jitter applied
199|   const pts = [
200|     [baseX, baseY],
201|     [baseX + w, baseY],
202|     [baseX + w, baseY + h],
203|     [baseX, baseY + h],
204|   ];
205|   return pts.map((p, i) => [p[0] + jitterPts[i][0], p[1] + jitterPts[i][1]]);
206| }
207| 
208| function drawJitterRect(x, y, w, h, jitterPts, fillStyle, shadow) {
209|   const pts = jitterPoly(x, y, w, h, jitterPts);
210|   ctx.save();
211|   if (shadow) {
212|     ctx.shadowColor = "rgba(61,64,91,0.35)";
213|     ctx.shadowBlur = 6;
214|     ctx.shadowOffsetY = 3;
215|   }
216|   ctx.fillStyle = fillStyle;
217|   ctx.beginPath();
218|   ctx.moveTo(pts[0][0], pts[0][1]);
219|   for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
220|   ctx.closePath();
221|   ctx.fill();
222|   ctx.restore();
223| }
224| 
225| function drawRoundedPlate(x, y, w, h, r, fillStyle) {
226|   ctx.save();
227|   ctx.shadowColor = "rgba(61,64,91,0.3)";
228|   ctx.shadowBlur = 6;
229|   ctx.shadowOffsetY = 3;
230|   ctx.fillStyle = fillStyle;
231|   ctx.beginPath();
232|   ctx.moveTo(x + r, y);
233|   ctx.arcTo(x + w, y, x + w, y + h, r);
234|   ctx.arcTo(x + w, y + h, x, y + h, r);
235|   ctx.arcTo(x, y + h, x, y, r);
236|   ctx.arcTo(x, y, x + w, y, r);
237|   ctx.closePath();
238|   ctx.fill();
239|   ctx.restore();
240| }
241| 
242| function drawCircleJitter(cx, cy, r, fillStyle, seedOffset) {
243|   const rand = mulberry32(Math.floor(cx * 13 + cy * 7 + seedOffset));
244|   ctx.save();
245|   ctx.shadowColor = "rgba(61,64,91,0.3)";
246|   ctx.shadowBlur = 6;
247|   ctx.shadowOffsetY = 3;
248|   ctx.fillStyle = fillStyle;
249|   ctx.beginPath();
250|   const segs = 16;
251|   for (let i = 0; i <= segs; i++) {
252|     const a = (i / segs) * Math.PI * 2;
253|     const jitter = (rand() - 0.5) * 1.6;
254|     const rr = r + jitter;
255|     const px = cx + Math.cos(a) * rr;
256|     const py = cy + Math.sin(a) * rr;
257|     if (i === 0) ctx.moveTo(px, py);
258|     else ctx.lineTo(px, py);
259|   }
260|   ctx.closePath();
261|   ctx.fill();
262|   ctx.restore();
263| }
264| 
265| // ---- Draw ----
266| function draw() {
267|   ctx.fillStyle = PALETTE.bg;
268|   ctx.fillRect(0, 0, W, H);
269| 
270|   // Title plate
271|   drawRoundedPlate(W / 2 - 140, 14, 280, 54, 14, PALETTE.accent);
272|   ctx.fillStyle = PALETTE.bg;
273|   ctx.font = "bold 24px system-ui, sans-serif";
274|   ctx.textAlign = "center";
275|   ctx.textBaseline = "middle";
276|   ctx.fillText("Tiny Maze", W / 2, 14 + 27);
277| 
278|   if (!running) {
279|     drawTitleScreen();
280|     return;
281|   }
282| 
283|   const m = boardMetrics();
284| 
285|   // Board background plate
286|   drawRoundedPlate(m.originX - 12, m.originY - 12, m.boardSize + 24, m.boardSize + 24, 18, PALETTE.accent);
287| 
288|   // Draw cells as separate layered tiles
289|   for (let y = 0; y < GRID; y++) {
290|     for (let x = 0; x < GRID; x++) {
291|       const px = m.originX + x * m.cellSize;
292|       const py = m.originY + y * m.cellSize;
293|       const inset = 2;
294|       let fill = PALETTE.layer;
295|       if (x === goalX && y === goalY) fill = PALETTE.highlight;
296|       drawJitterRect(
297|         px + inset,
298|         py + inset,
299|         m.cellSize - inset * 2,
300|         m.cellSize - inset * 2,
301|         cellJitter[y][x],
302|         fill,
303|         true
304|       );
305|     }
306|   }
307| 
308|   // Draw walls as accent-colored thick lines
309|   ctx.strokeStyle = PALETTE.accent;
310|   ctx.lineWidth = Math.max(3, m.cellSize * 0.08);
311|   ctx.lineCap = "round";
312|   for (let y = 0; y < GRID; y++) {
313|     for (let x = 0; x < GRID; x++) {
314|       const px = m.originX + x * m.cellSize;
315|       const py = m.originY + y * m.cellSize;
316|       const c = cells[y][x];
317|       ctx.beginPath();
318|       if (c.N) { ctx.moveTo(px, py); ctx.lineTo(px + m.cellSize, py); }
319|       if (c.S) { ctx.moveTo(px, py + m.cellSize); ctx.lineTo(px + m.cellSize, py + m.cellSize); }
320|       if (c.W) { ctx.moveTo(px, py); ctx.lineTo(px, py + m.cellSize); }
321|       if (c.E) { ctx.moveTo(px + m.cellSize, py); ctx.lineTo(px + m.cellSize, py + m.cellSize); }
322|       ctx.stroke();
323|     }
324|   }
325| 
326|   // Highlight legal moves from current position
327|   const dirs = [
328|     ["N", 0, -1], ["S", 0, 1], ["E", 1, 0], ["W", -1, 0],
329|   ];
330|   for (const [dir, dx, dy] of dirs) {
331|     if (canMove(playerX, playerY, dir)) {
332|       const nx = playerX + dx, ny = playerY + dy;
333|       const c = cellCenter(nx, ny);
334|       ctx.save();
335|       ctx.globalAlpha = 0.35;
336|       ctx.fillStyle = PALETTE.highlight;
337|       ctx.beginPath();
338|       ctx.arc(c.cx, c.cy, m.cellSize * 0.12, 0, Math.PI * 2);
339|       ctx.fill();
340|       ctx.restore();
341|     }
342|   }
343| 
344|   // Goal marker (small flag shape) if not player there
345|   {
346|     const g = cellCenter(goalX, goalY);
347|     ctx.save();
348|     ctx.fillStyle = PALETTE.accent;
349|     ctx.font = "bold " + Math.floor(m.cellSize * 0.4) + "px system-ui, sans-serif";
350|     ctx.textAlign = "center";
351|     ctx.textBaseline = "middle";
352|     ctx.fillText("\u2605", g.cx, g.cy);
353|     ctx.restore();
354|   }
355| 
356|   // Player piece
357|   {
358|     const p = cellCenter(playerX, playerY);
359|     drawCircleJitter(p.cx, p.cy, m.cellSize * 0.28, PALETTE.accent, 42);
360|     drawCircleJitter(p.cx, p.cy, m.cellSize * 0.2, PALETTE.highlight, 77);
361|   }
362| 
363|   // Score / moves plate
364|   drawRoundedPlate(16, H - 60, 160, 44, 12, PALETTE.accent);
365|   ctx.fillStyle = PALETTE.bg;
366|   ctx.font = "bold 18px system-ui, sans-serif";
367|   ctx.textAlign = "left";
368|   ctx.textBaseline = "middle";
369|   ctx.fillText("Moves: " + moves, 30, H - 60 + 22);
370| 
371|   drawRoundedPlate(W - 176, H - 60, 160, 44, 12, PALETTE.accent);
372|   ctx.textAlign = "right";
373|   ctx.fillText("Score: " + score, W - 30, H - 60 + 22);
374| 
375|   if (paused) {
376|     ctx.save();
377|     ctx.fillStyle = "rgba(61,64,91,0.6)";
378|     ctx.fillRect(0, 0, W, H);
379|     drawRoundedPlate(W / 2 - 100, H / 2 - 30, 200, 60, 14, PALETTE.bg);
380|     ctx.fillStyle = PALETTE.accent;
381|     ctx.font = "bold 22px system-ui, sans-serif";
382|     ctx.textAlign = "center";
383|     ctx.textBaseline = "middle";
384|     ctx.fillText("Paused", W / 2, H / 2);
385|     ctx.restore();
386|   }
387| 
388|   if (gameEnded) {
389|     ctx.save();
390|     ctx.fillStyle = "rgba(61,64,91,0.55)";
391|     ctx.fillRect(0, 0, W, H);
392|     drawRoundedPlate(W / 2 - 150, H / 2 - 60, 300, 120, 18, PALETTE.bg);
393|     ctx.fillStyle = PALETTE.accent;
394|     ctx.font = "bold 26px system-ui, sans-serif";
395|     ctx.textAlign = "center";
396|     ctx.textBaseline = "middle";
397|     ctx.fillText(endMessage, W / 2, H / 2 - 15);
398|     ctx.font = "18px system-ui, sans-serif";
399|     ctx.fillText("Tap to play again", W / 2, H / 2 + 20);
400|     ctx.restore();
401|   }
402| }
403| 
404| let pulsePhase = 0;
405| function drawTitleScreen() {
406|   const m = boardMetrics();
407|   drawRoundedPlate(m.originX - 12, m.originY - 12, m.boardSize + 24, m.boardSize + 24, 18, PALETTE.accent);
408|   // draw a decorative mini pattern
409|   ctx.save();
410|   ctx.fillStyle = PALETTE.layer;
411|   const cs = m.boardSize / GRID;
412|   for (let y = 0; y < GRID; y++) {
413|     for (let x = 0; x < GRID; x++) {
414|       const px = m.originX + x * cs + 2;
415|       const py = m.originY + y * cs + 2;
416|       ctx.globalAlpha = 0.5 + 0.5 * Math.sin((x + y) * 0.6);
417|       ctx.fillRect(px, py, cs - 4, cs - 4);
418|     }
419|   }
420|   ctx.restore();
421| 
422|   pulsePhase += 0.05;
423|   const alpha = 0.6 + 0.4 * Math.sin(pulsePhase);
424|   drawRoundedPlate(W / 2 - 130, H / 2 - 30, 260, 60, 16, PALETTE.accent);
425|   ctx.save();
426|   ctx.globalAlpha = alpha;
427|   ctx.fillStyle = PALETTE.bg;
428|   ctx.font = "bold 22px system-ui, sans-serif";
429|   ctx.textAlign = "center";
430|   ctx.textBaseline = "middle";
431|   ctx.fillText("Tap to begin", W / 2, H / 2);
432|   ctx.restore();
433| }
434| 
435| // ---- Game state control ----
436| let gameEnded = false;
437| let endMessage = "";
438| 
439| function backToTitle() {
440|   running = false;
441|   gameEnded = false;
442|   paused = false;
443|   draw();
444| }
445| 
446| function startGame() {
447|   newGame();
448|   gameEnded = false;
449|   level = 1;
450|   CARTRIDGE.send("level", { index: level });
451|   draw();
452| }
453| 
454| function onCellTapped(gx, gy) {
455|   if (gameEnded) return;
456|   const dx = gx - playerX;
457|   const dy = gy - playerY;
458|   if (Math.abs(dx) + Math.abs(dy) !== 1) return; // must be adjacent
459|   let dir = null;
460|   if (dx === 1) dir = "E";
461|   else if (dx === -1) dir = "W";
462|   else if (dy === 1) dir = "S";
463|   else if (dy === -1) dir = "N";
464|   if (!dir) return;
465|   if (!canMove(playerX, playerY, dir)) return;
466| 
467|   playerX = gx;
468|   playerY = gy;
469|   moves += 1;
470|   score += 1;
471|   CARTRIDGE.send("score", { value: score });
472| 
473|   if (solved()) {
474|     gameEnded = true;
475|     endMessage = "You escaped!";
476|     CARTRIDGE.send("end", { reason: "win", value: moves });
477|   } else if (!anyLegalMove()) {
478|     gameEnded = true;
479|     endMessage = "Dead end!";
480|     CARTRIDGE.send("end", { reason: "stuck" });
481|   }
482|   draw();
483| }
484| 
485| // ---- Input ----
486| canvas.style.touchAction = "none";
487| canvas.addEventListener("pointerdown", (event) => {
488|   event.preventDefault();
489|   if (paused) return;
490| 
491|   if (!running) {
492|     running = true;
493|     startGame();
494|     CARTRIDGE.send("start");
495|     return;
496|   }
497| 
498|   if (gameEnded) {
499|     // start a fresh maze
500|     startGame();
501|     return;
502|   }
503| 
504|   const rect = canvas.getBoundingClientRect();
505|   const px = event.clientX - rect.left;
506|   const py = event.clientY - rect.top;
507|   const tile = tileAt(px, py);
508|   if (tile) onCellTapped(tile.gx, tile.gy);
509| });
510| 
511| // ---- Host command bridge ----
512| window.addEventListener("message", (event) => {
513|   const data = event.data;
514|   if (!data || data.source !== "cartridge-host") return;
515|   if (data.type === "pause") paused = true;
516|   if (data.type === "resume") paused = false;
517|   if (data.type === "reset") backToTitle();
518| });
519| 
520| // ---- Animation loop (for title pulse) ----
521| function loop() {
522|   if (!paused) {
523|     if (!running) draw();
524|   }
525|   requestAnimationFrame(loop);
526| }
527| 
528| // ---- Init ----
529| resize();
530| newGame();
531| draw();
532| if (!booted) {
533|   booted = true;
534|   CARTRIDGE.send("boot", { title: "Tiny Maze", gameType: "puzzle-board", lang: "en" });
535| }
536| requestAnimationFrame(loop);
537| </script>
538| </body>
539| </html>
